file.content:
                description,
                strict,
            },
    }) => Some(
        OutputFormat::builder()
            .r#type(OutputFormatType::JsonSchema)
            .structure(OutputFormatStructure::JsonSchema(
                JsonSchemaDefinition::builder()
                    .schema(schema)
                    .name(name)
                    .description(description)
                    .build()
                    .map_err(|e| to_api_error(e.to_string()))?,
            ))
            .build()
            .map_err(|e| to_api_error(e.to_string()))?,
    ),
    _ => None,
};

